function jrHome(){return `<div class="jr-home">
 <section class="jr-hero"><div class="hero-visual" aria-label="James Real luxury living concept"><img class="hero-photo hq-photo" src="assets/san-francisco-headquarters-full.png" alt="Proposed James Real headquarters in San Francisco, with sculptural towers and gold brand signage at sunset" fetchpriority="high"><div class="hero-shade"></div></div><div class="hero-editorial"><p class="eyebrow">JAMES REAL / SAN FRANCISCO</p><h1>A place for<br><span>our world.</span></h1><p class="hero-description">A headquarters imagined for San Francisco. One address for our interests in food, style, spaces, journeys, learning, and the pleasure of time well spent.</p><div class="hero-cta"><button class="button" data-explore>Discover the six worlds <span>↓</span></button><button class="film-button" data-replay><span>▷</span> Our brand film</button></div></div><div class="hero-caption"><span>PROPOSED HEADQUARTERS / ARCHITECTURAL CONCEPT</span><span>01 — 06</span></div><div class="hero-bottom"><span>FOR THE PLEASURE OF LIVING</span><span>SCROLL TO DISCOVER ↓</span></div></section>
 <section class="hq-introduction"><div><p class="eyebrow">THE JAMES REAL HOUSE</p><h2>One house.<br>Many ways to live.</h2><p>Curved bronze, warm stone, and an entrance open to the city. Our proposed San Francisco headquarters gives physical form to six connected interests.</p><p class="fine">Architectural concept illustration. This building is a proposed design, not an operating headquarters or a commissioned architect’s project.</p></div><figure><img src="assets/san-francisco-headquarters.png" alt="James Real headquarters entrance and warm gold signage" loading="lazy"><figcaption>The arrival · San Francisco headquarters concept</figcaption></figure></section><div class="world-index">${JR_WORLDS.map((w,i)=>`<button data-world-scroll="${w.id}"><small>0${i+1}</small><b>${w.en}</b><i>↗</i></button>`).join('')}</div>
 <section class="collection-section" id="collection"><div class="collection-heading"><div><p class="eyebrow">SIX PARTS OF EVERYDAY LIFE</p><h2>A point of view.<br><span>Six ways to live it.</span></h2></div><p>From the table to the places we call home,<br>our interests belong together.<br><small>Explore the spaces, objects, and details behind each world.</small></p></div><div class="world-grid">${JR_WORLDS.map((w,i)=>`<article class="world-card" id="world-${w.id}"><button class="world-image" data-gallery="${w.id}" aria-label="Explore ${w.en} collection"><svg viewBox="1040 0 496 518" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><image href="assets/${w.id}-contexts.png" width="1536" height="1024"/></svg><span class="world-number">0${i+1}</span><span class="world-open">View the world ↗</span></button><div class="world-copy"><div class="world-title"><h3>${w.en}</h3><span class="world-rule"></span></div><h4>${w.title}</h4><p>${w.desc}</p><div class="world-actions"><span>${w.tags}</span><button data-gallery="${w.id}" data-mode="products" aria-label="View ${w.zh} objects and details">Objects & details ＋</button></div></div></article>`).join('')}</div></section>
 <section class="brand-manifesto"><div class="manifesto-image"><img src="assets/logo-C.svg" alt="James Real couple emblem"></div><div><p class="eyebrow">THE JAMES REAL POINT OF VIEW</p><h2>Choose with care.<br>Enjoy without hurry.</h2><p>We are drawn to things that deserve a second look: the curve of a glass, the feel of a fabric, the way a room welcomes you.<br><br>For James Real, luxury is the attention we give to everyday life — and the time we leave to enjoy it.</p><img src="assets/logo-F.svg" alt="James Real signature" class="manifesto-signature"></div></section>
 <section class="daily-section"><div class="section-heading"><div><p class="eyebrow">THE JOURNAL</p><h2>Something to read. Something to try.</h2></div><span>News, useful references, and ideas to take into your day.</span></div><div class="daily-grid">${[['01','World & SI','World & SI','Read a selection of international headlines and reports on intelligence and technology.','news','◎'],['02','Global markets','Global markets','Compare benchmark indices, with dated quotes and links to the original sources.','markets','↗'],['03','Healthy living','Healthy living','Find food, movement, and nutrition references for each stage of life.','health','♡'],['04','Family kitchen','Family kitchen','Find a dish for six, save a favourite, and bring something new to the table.','recipes','♧'],['05','Everyday English','Everyday English','Choose your level, listen, and practise with eleven cards per edition.','english','Aa']].map(x=>`<a class="daily-link" href="#${x[4]}"><div class="daily-top"><small>${x[0]}</small><span>${x[5]}</span></div><h3>${x[1]}</h3><p>${x[3]}</p><b>Explore <span>↗</span></b></a>`).join('')}</div></section>
 <section class="english-teaser"><div><p class="eyebrow">EVERYDAY ENGLISH / A1–C2</p><h2>Find the words.<br>Use them today.</h2><p>Start at your level. Read a card, listen to the example,<br>then try the question before revealing the answer.<br>Every edition ends with a four-paragraph essay.</p><a class="button" href="#english">Discover Everyday English ↗</a></div><div class="level-sculpture"><span>A1</span><span>A2</span><span>B1</span><span>B2</span><span>C1</span><span>C2</span><small>6 LEVELS · 11 CARDS PER LEVEL</small></div></section>

 </div>`}

let jrGalleryWorld=JR_WORLDS[0];
function showGallery(id,mode='contexts'){jrGalleryWorld=JR_WORLDS.find(w=>w.id===id)||JR_WORLDS[0];const d=document.querySelector('#gallery');document.querySelector('#gallery-title').textContent=`${jrGalleryWorld.en}`;setGalleryMode(mode);if(!d.open)d.showModal();document.body.classList.add('dialog-open')}
function setGalleryMode(mode){document.querySelector('#gallery-tabs').innerHTML=['contexts','products'].map(m=>`<button data-gallery-mode="${m}" class="${m===mode?'selected':''}" aria-pressed="${m===mode}">${m==='contexts'?'The experience':'Objects & details'}</button>`).join('');document.querySelector('#gallery-image').src=`assets/${jrGalleryWorld.id}-${mode}.png`;document.querySelector('#gallery-image').alt=`James Real ${jrGalleryWorld.zh} ${mode==='contexts'?'The experience':'Objects & details'}complete concept collection`}
document.querySelector('#gallery-close').onclick=()=>document.querySelector('#gallery').close();
document.querySelector('#gallery').addEventListener('close',()=>document.body.classList.remove('dialog-open'));
document.querySelector('#gallery').addEventListener('click',e=>{if(e.target.id==='gallery')e.target.close()});
document.addEventListener('click',event=>{const b=event.target.closest('[data-gallery],[data-gallery-mode],[data-explore],[data-world-scroll],[data-replay]');if(!b)return;if(b.hasAttribute('data-gallery'))showGallery(b.dataset.gallery,b.dataset.mode||'contexts');if(b.hasAttribute('data-gallery-mode'))setGalleryMode(b.dataset.galleryMode);if(b.hasAttribute('data-explore'))document.querySelector('#collection')?.scrollIntoView({behavior:'smooth'});if(b.hasAttribute('data-world-scroll'))document.querySelector('#world-'+b.dataset.worldScroll)?.scrollIntoView({behavior:'smooth',block:'center'});if(b.hasAttribute('data-replay'))playIntro()});

// Brand film is initialized in brand-film.js.

/* Original dated English content is retained as a separately labelled archive. */
let jrLegacyDate='2026-10-11', jrLegacyEdition=null, jrLegacyOpen=false;
function legacyArchiveHTML(){return `<section class="legacy-archive"><details id="legacy-archive" ${jrLegacyOpen?'open':''}><summary>Lesson archive <span>Mixed B2–C2 editions ↗</span></summary><div class="legacy-toolbar"><label>Edition date <select id="legacy-date">${['06','07','08','09','10','11'].map(d=>`<option value="2026-10-${d}" ${jrLegacyDate==='2026-10-'+d?'selected':''}>2026-10-${d}</option>`).join('')}</select></label><p>Browse the original mixed-level lessons by date.</p></div><div id="legacy-cards">${jrLegacyEdition?legacyCardsHTML(jrLegacyEdition):'<button id="load-legacy" class="button secondary">View original cards</button>'}</div></details></section>`}
function legacyCardsHTML(edition){return `<p class="fine">${escapeHTML(edition.theme||'')} · ${escapeHTML(edition.date)} · ${edition.lessons.length} cards</p><div class="legacy-grid">${edition.lessons.map(l=>`<article class="legacy-card"><img class="legacy-poster" loading="lazy" src="data/english-images/${edition.date}/${encodeURIComponent(l.filename||l.id+'.png')}" alt="${escapeHTML(l.title)} — original complete card"><small>${escapeHTML(l.level)} / ${escapeHTML(l.image)}</small><h3>${escapeHTML(l.title)}</h3><p>${escapeHTML(l.meaning)}</p>${l.ipa?`<p>${escapeHTML(l.ipa)} · ${escapeHTML(l.partOfSpeech)}</p>`:''}${l.synonyms?.length?`<p>Synonyms: ${escapeHTML(l.synonyms.join('; '))}</p>`:''}<p>${escapeHTML(l.example)}</p>${l.paragraphs?l.paragraphs.map(p=>`<p>${escapeHTML(Array.isArray(p)?p.join(' '):p)}</p>`).join(''):''}<p>${escapeHTML(l.notes)}</p><p class="legacy-conversation">${escapeHTML(l.conversation||'').replace(/\\n/g,'<br>').replace(/\n/g,'<br>')}</p>${l.structure?`<p>${escapeHTML(l.structure)}</p>`:''}<details><summary>Your turn</summary><p>${escapeHTML(l.exercise)}</p></details></article>`).join('')}</div>`}
async function loadLegacy(){jrLegacyOpen=true;const target=document.querySelector('#legacy-cards');if(!target)return;target.textContent='Loading original cards…';try{const r=await fetch('data/english-archive/'+jrLegacyDate+'.json');if(!r.ok)throw Error();jrLegacyEdition=await r.json();target.innerHTML=legacyCardsHTML(jrLegacyEdition)}catch{target.textContent='The archive could not load. Please try again.'}}
document.addEventListener('click',e=>{if(e.target.closest('#load-legacy'))loadLegacy()});document.addEventListener('change',e=>{if(e.target.id==='legacy-date'){jrLegacyDate=e.target.value;loadLegacy()}});

const jrBaseRender=render;
render=function(){jrBaseRender();const route=main.dataset.route;document.body.dataset.route=route;document.documentElement.lang=currentLanguage==='en'?'en':currentLanguage;document.querySelector('#language').disabled=['home','english','recipes'].includes(route);document.querySelector('#language').title=['home','english','recipes'].includes(route)?'This page is presented in English.':'Choose a translation for the source content';if(route==='english'){main.insertAdjacentHTML('beforeend',legacyArchiveHTML());window.jrEnglishInit?.()}if(route==='home'){document.title='James Real — Life is in the details.'}document.querySelector('footer').hidden=false};
render();

